using System.Text.Json.Serialization;
using ElectronicRegisterAPI.Domain.Enums;
using ElectronicRegisterAPI.Domain.Models;

namespace ElectronicRegisterAPI.Api.Contracts;

// No institution field: the institution always comes from the access token. No email
// field: the platform address is generated by the server. Unknown fields (an "email",
// an extra "role", an "institutionId") are rejected for every caller.
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed class CreateInstitutionAccountRequest
{
    [JsonRequired]
    public Guid EventId { get; init; }

    [JsonRequired]
    public string FirstName { get; init; } = "";

    [JsonRequired]
    public string LastName { get; init; } = "";

    [JsonRequired]
    public string FiscalCode { get; init; } = "";

    [JsonRequired]
    public string[] Roles { get; init; } = [];

    public Guid? StudentId { get; init; }
    public Guid? TeacherId { get; init; }
    public Guid? ClassId { get; init; }

    [JsonRequired]
    public string Reason { get; init; } = "";

    internal CreateInstitutionAccount ToDomain()
    {
        if (Roles is null || Roles.Length == 0)
            throw new ArgumentException("Indicare almeno un ruolo.");
        if (Roles.Any(r => !Enum.GetNames<InstitutionRole>().Contains(r, StringComparer.Ordinal)))
            throw new ArgumentException("Ruolo sconosciuto: ammessi InstitutionAdmin, Staff, Teacher, Student.");
        if (FirstName is null || LastName is null || FiscalCode is null || Reason is null)
            throw new ArgumentException("Nome, cognome, codice fiscale e motivazione sono obbligatori.");
        return new(EventId, FirstName, LastName, FiscalCode, Roles.Select(Enum.Parse<InstitutionRole>).ToArray(), StudentId, TeacherId, ClassId, Reason);
    }
}
